// Compile-time embedded frontend assets, served over the custom protocol.
//
// Deliberately not `rust-embed`: that pulls a proc-macro crate plus `walkdir`,
// `sha2`, and friends to do what `include_bytes!` already does. The builder is
// generated by the CLI's build step, which already knows the asset list.

use std::borrow::Cow;

/// A generated table of `(absolute-path-in-built-output, bytes)`.
///
/// The CLI writes this file; `include!` -ing it means the payload lands in the
/// binary at compile time with no runtime filesystem access.
pub type AssetTable = &'static [(&'static str, &'static [u8])];

/// Look up a URL path in the asset table.
///
/// Returns `None` when nothing matches. The root serves `index.html`, and so
/// does a navigation path with no file extension (`/notes/42`, `/docs/`),
/// because that is a client-side route in a bundled SPA and only the page's own
/// router can answer it. A missing path *with* an extension (`/assets/gone.js`)
/// is a genuinely missing asset and stays a miss, so a broken script import is
/// reported as a 404 rather than as HTML the parser rejects.
///
/// The table is the only thing consulted, so a path still cannot escape it.
pub fn lookup<'a>(assets: AssetTable, path: &str) -> Option<(&'a str, Cow<'a, [u8]>)> {
    let path = if path.is_empty() || path == "/" {
        "/index.html"
    } else {
        path
    };
    let path = path.trim_start_matches('/');

    if let Some(hit) = find(assets, path) {
        return Some(hit);
    }
    // A route, not a file: no extension, and no `..` segment that would make it
    // a traversal attempt rather than a route.
    let leaf = path.rsplit('/').next().unwrap_or("");
    let is_route = !leaf.contains('.') && !path.split('/').any(|segment| segment == "..");
    if is_route {
        return find(assets, "index.html");
    }
    None
}

fn find<'a>(assets: AssetTable, path: &str) -> Option<(&'a str, Cow<'a, [u8]>)> {
    // The generator sorts by path, so a page that requests many modules pays a
    // binary search instead of a scan. A table from an older generator may be
    // unsorted: a miss then falls back to the scan, and an accidental hit is
    // still a genuine match because binary_search only reports exact equality.
    if assets.len() > 8 {
        if let Ok(index) = assets.binary_search_by(|(name, _)| (*name).cmp(path)) {
            let (name, bytes) = assets[index];
            return Some((name, Cow::Borrowed(bytes)));
        }
    }
    assets
        .iter()
        .find(|(name, _)| *name == path)
        .map(|(name, bytes)| (*name, Cow::Borrowed(*bytes)))
}

/// Content type for a path, by extension.
///
/// A hand-written table instead of the `mime_guess` crate: a desktop app serves
/// maybe a dozen file types, and this keeps the dependency tree at wry+tao+serde_json.
pub fn content_type(path: &str) -> &'static str {
    let ext = path.rsplit('.').next().unwrap_or("");
    match ext {
        "html" | "htm" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "wasm" => "application/wasm",
        "txt" => "text/plain; charset=utf-8",
        "map" => "application/json",
        _ => "application/octet-stream",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    static ASSETS: AssetTable = &[
        ("index.html", b"<html></html>"),
        ("assets/app.js", b"console.log(1)"),
    ];

    #[test]
    fn root_serves_index() {
        assert_eq!(lookup(ASSETS, "/").unwrap().0, "index.html");
        assert_eq!(lookup(ASSETS, "").unwrap().0, "index.html");
    }

    #[test]
    fn nested_paths_resolve() {
        assert_eq!(lookup(ASSETS, "/assets/app.js").unwrap().0, "assets/app.js");
    }

    #[test]
    fn a_client_side_route_serves_index() {
        assert_eq!(lookup(ASSETS, "/notes/42").unwrap().0, "index.html");
        assert_eq!(lookup(ASSETS, "/docs/").unwrap().0, "index.html");
        assert_eq!(lookup(ASSETS, "/settings/about").unwrap().0, "index.html");
    }

    #[test]
    fn a_large_sorted_table_finds_files_and_falls_back_for_old_tables() {
        static SORTED: &[(&str, &[u8])] = &[
            ("a.js", b"a"),
            ("b.js", b"b"),
            ("c.js", b"c"),
            ("d.js", b"d"),
            ("e.js", b"e"),
            ("f.js", b"f"),
            ("g.js", b"g"),
            ("h.js", b"h"),
            ("index.html", b"index"),
            ("z.js", b"z"),
        ];
        assert_eq!(lookup(SORTED, "/index.html").unwrap().0, "index.html");
        assert_eq!(lookup(SORTED, "/c.js").unwrap().0, "c.js");
        assert!(lookup(SORTED, "/missing.js").is_none());

        // An older generated table is not guaranteed to be sorted; the scan
        // fallback keeps it authoritative.
        static UNSORTED: &[(&str, &[u8])] = &[
            ("z.js", b"z"),
            ("b.js", b"b"),
            ("c.js", b"c"),
            ("d.js", b"d"),
            ("e.js", b"e"),
            ("f.js", b"f"),
            ("g.js", b"g"),
            ("h.js", b"h"),
            ("index.html", b"index"),
            ("a.js", b"a"),
        ];
        assert_eq!(lookup(UNSORTED, "/a.js").unwrap().0, "a.js");
        assert_eq!(lookup(UNSORTED, "/z.js").unwrap().0, "z.js");
    }

    /// Ignored by default: a measurement, not a gate. Run with
    /// `cargo test --release --lib bench_asset_lookup -- --ignored --nocapture`.
    #[test]
    #[ignore]
    fn bench_asset_lookup() {
        use std::hint::black_box;
        use std::time::Instant;

        let mut entries: Vec<(&'static str, &'static [u8])> = (0..512)
            .map(|i: usize| {
                let name: &'static str = Box::leak(format!("assets/{i:03}.js").into_boxed_str());
                (name, b"x" as &'static [u8])
            })
            .collect();
        let sorted: AssetTable = Box::leak(entries.clone().into_boxed_slice());
        entries.reverse();
        let unsorted: AssetTable = Box::leak(entries.into_boxed_slice());

        let lookups = 2_000_000u32;
        let time = |table: AssetTable| {
            let start = Instant::now();
            let mut found = 0u32;
            for i in 0..lookups {
                let path = format!("/assets/{:03}.js", i % 512);
                if lookup(black_box(table), black_box(&path)).is_some() {
                    found += 1;
                }
            }
            (start.elapsed(), found)
        };
        // Warm the branch predictor and the allocation path once.
        let _ = time(sorted);
        let (sorted_time, found) = time(sorted);
        let (unsorted_time, found_unsorted) = time(unsorted);
        assert_eq!(found, lookups);
        assert_eq!(found_unsorted, lookups);
        println!(
            "binary search: {:?} total, {:.1} ns/lookup",
            sorted_time,
            sorted_time.as_nanos() as f64 / lookups as f64
        );
        println!(
            "fallback scan: {:?} total, {:.1} ns/lookup",
            unsorted_time,
            unsorted_time.as_nanos() as f64 / lookups as f64
        );
    }

    #[test]
    fn a_missing_asset_stays_a_miss() {
        assert!(lookup(ASSETS, "/assets/gone.js").is_none());
        assert!(lookup(ASSETS, "/missing.css").is_none());
        assert!(lookup(ASSETS, "/logo.png").is_none());
    }

    #[test]
    fn traversal_does_not_escape_the_table() {
        assert!(lookup(ASSETS, "/../../etc/passwd").is_none());
        assert!(lookup(ASSETS, "/assets/../../../secret").is_none());
    }

    #[test]
    fn mime_table_covers_the_scaffold_types() {
        assert!(content_type("x.js").starts_with("text/javascript"));
        assert!(content_type("x.css").starts_with("text/css"));
        assert_eq!(content_type("x.unknown"), "application/octet-stream");
        assert_eq!(content_type("nested/dir/app.wasm"), "application/wasm");
    }
}
